(() => {
    const form = document.querySelector('#commentForm');
    const parentInput = form?.querySelector('input[name="parent_id"]');
    const contentInput = form?.querySelector('[name="content"]');
    const replyContext = form?.querySelector('#commentReplyContext');

    if (!form || !parentInput) {
        return;
    }

    document.querySelectorAll('a.reply').forEach((replyLink) => {
        replyLink.addEventListener('click', (event) => {
            event.preventDefault();
            parentInput.value = replyLink.dataset.id ?? '';

            if (replyContext) {
                const author = replyContext.querySelector('[data-reply-author]');
                const content = replyContext.querySelector('[data-reply-content]');
                if (author) {
                    author.textContent = replyLink.dataset.author ?? '';
                }
                if (content) {
                    content.textContent = replyLink.dataset.content ?? '';
                }
                replyContext.hidden = false;
            }

            form.scrollIntoView({behavior: 'smooth', block: 'start'});
            window.setTimeout(() => contentInput?.focus({preventScroll: true}), 300);
        });
    });

    replyContext?.querySelector('[data-cancel-reply]')?.addEventListener('click', () => {
        parentInput.value = '';
        replyContext.hidden = true;
        contentInput?.focus();
    });
})();
